{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年华东地区已完成订单销售额城市排名Top3",
      "business_question": "2026年华东地区已完成订单的销售额按城市汇总后，降序排名前三名的城市及其销售额分别是多少？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：分析2026年华东地区已完成订单的销售额，按城市汇总并降序排名，取前三名。删除此任务将无法提供决策所需的关键数据视图。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "gte",
                "value": "2026-01-01"
              },
              {
                "field": "field_0001",
                "operator": "lt",
                "value": "2027-01-01"
              },
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "华东"
              },
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "sales_sum",
            "direction": "desc",
            "n": 3
          }
        }
      ]
    }
  ]
}
